/**
 * Test support (Phase 9, Workflow 9B; C164.1-C164.6; `analytics-logic`): a seeded synthetic
 * population of inquiries, their steps, verification attempts, check results, signals and cases,
 * described one person at a time, and the rollup rows it yields. The golden tests compute every
 * metric twice: by its definition over the people (`reference`, here) and through `metrics.ts` over
 * the rows, so a column mapped to the wrong metric, a source left out or a rate over the wrong
 * denominator shows. Generated by code from a fixed seed (rule 9): no real person, ids `synthetic`.
 * Not exported from the package root.
 */
import { createHash } from 'node:crypto';
import type { AnalyticsCheckStatus, AnalyticsRollupSource } from '../definitions.js';
import { DURATION_BUCKET_COUNT, durationBucketOf } from '../durations.js';
import { ANALYTICS_FLOW_START_STEP_ID } from '../rows.js';
import type {
  AnalyticsCaseAssigneeDailyRow,
  AnalyticsCaseDailyRow,
  AnalyticsCheckDailyRow,
  AnalyticsCheckReasonDailyRow,
  AnalyticsInquiryDailyRow,
  AnalyticsPathDailyRow,
  AnalyticsRowKey,
  AnalyticsSignalDailyRow,
  AnalyticsStepDailyRow,
  AnalyticsTransitionDailyRow,
  AnalyticsVerificationDailyRow,
  AnalyticsVerificationStepDailyRow,
} from '../rows.js';
import { signalBinOf } from '../signal-bins.js';
import { seededRandom, type SeededRandom } from './random.js';

export const ENVIRONMENT = 'env_synthetic0000000000000001';
export const TIME_ZONE = 'Europe/Paris';
export const TEMPLATE = 'itmpl_synthetic000000000000001';
export const VERSION = 'itmplv_synthetic00000000000001';
export const CASE_TEMPLATE = 'ctmpl_synthetic00000000000001';
export const STEPS = ['start', 'details', 'document', 'selfie', 'review', 'done'] as const;
export const DAYS = ['2026-03-02', '2026-03-03', '2026-03-04', '2026-03-05'] as const;

type Status = 'completed' | 'failed' | 'approved' | 'declined' | 'needs_review';
type Split = 'verified' | 'with-fallback' | 'unverified';

export interface Person {
  readonly day: string;
  readonly source: AnalyticsRollupSource;
  readonly platform: 'web' | 'android' | null;
  readonly deviceKind: 'desktop-web' | 'mobile-web' | 'native' | null;
  readonly started: boolean;
  readonly expiredBeforeStart: boolean;
  readonly interacted: boolean;
  readonly finished: boolean;
  readonly expiredAfterStart: boolean;
  readonly status: Status | null;
  readonly split: Split | null;
  readonly markedForReview: boolean;
  readonly decided: 'automatic' | 'manual' | 'not-declared' | null;
  readonly finishSeconds: number | null;
  /** The person-visible steps in the order entered (revisits included). */
  readonly path: readonly string[];
  readonly attempts: readonly {
    readonly type: 'government-id' | 'selfie';
    readonly captureMethod: 'upload' | 'camera' | null;
    readonly country: string | null;
    readonly status:
      | 'initiated'
      | 'passed'
      | 'failed'
      | 'requires_retry'
      | 'needs_review'
      | 'canceled'
      | 'skipped';
  }[];
  readonly checks: readonly {
    readonly name: string;
    readonly status: AnalyticsCheckStatus;
    readonly reasons: readonly string[];
  }[];
  readonly signals: Readonly<Record<string, unknown>>;
}

export interface CaseRecord {
  readonly day: string;
  readonly source: AnalyticsRollupSource;
  readonly resolved: boolean;
  readonly slaMet: boolean;
  readonly slaMissed: boolean;
  readonly resolutionSeconds: number | null;
  readonly assignee: string | null;
}

export const CHECKS = ['id_barcode_detection', 'id_expiration_detection'] as const;
const REASONS = ['execution_error', 'input_missing', 'barcode_not_found'] as const;

function person(random: SeededRandom, day: string): Person {
  const started = random.chance(0.9);
  const finished = started && random.chance(0.8);
  const expiredAfterStart = started && !finished && random.chance(0.7);
  const status = finished
    ? random.pick<Status>([
        'completed',
        'completed',
        'failed',
        'approved',
        'declined',
        'needs_review',
      ])
    : null;
  const path = started ? walk(random, finished) : [];
  const attempts = path.includes('document')
    ? Array.from({ length: random.int(1, 3) }, () => ({
        type: random.pick(['government-id', 'selfie'] as const),
        captureMethod: random.pick(['upload', 'camera', null] as const),
        country: random.pick(['FR', 'DE', null] as const),
        status: random.pick([
          'initiated',
          'passed',
          'passed',
          'failed',
          'requires_retry',
          'needs_review',
          'canceled',
          'skipped',
        ] as const),
      }))
    : [];
  return {
    day,
    source: random.chance(0.15) ? 'redacted' : 'facts',
    platform: random.pick(['web', 'android', null] as const),
    deviceKind: random.pick(['desktop-web', 'mobile-web', 'native', null] as const),
    started,
    expiredBeforeStart: !started && random.chance(0.6),
    interacted: started && path.length > 1,
    finished,
    expiredAfterStart,
    status,
    split:
      status === 'completed'
        ? random.pick<Split>(['verified', 'with-fallback', 'unverified'])
        : null,
    markedForReview: finished && random.chance(0.2),
    decided:
      status === 'approved' || status === 'declined'
        ? random.pick(['automatic', 'manual', 'not-declared'] as const)
        : null,
    finishSeconds: finished ? Math.exp(random.next() * Math.log(86_400 * 3)) : null,
    path,
    attempts,
    checks:
      attempts.length === 0
        ? []
        : CHECKS.map((name) => {
            const checkStatus = random.pick<AnalyticsCheckStatus>([
              'passed',
              'passed',
              'failed',
              'not_applicable',
              'errored',
              'not_configured',
              'pending',
            ]);
            return {
              name,
              status: checkStatus,
              reasons:
                checkStatus === 'failed' || checkStatus === 'errored'
                  ? [random.pick(REASONS), ...(random.chance(0.3) ? [random.pick(REASONS)] : [])]
                  : [],
            };
          }),
    signals: {
      'inquiry/bot_score': random.chance(0.2) ? null : random.int(0, 100),
      'inquiry/tor_detected': random.pick([true, false, null]),
      'inquiry/country_from_session': random.pick(['FR', 'DE', 'JP', null]),
      'inquiry/max_session_distance': random.chance(0.3) ? null : random.int(0, 3_000_000),
    },
  };
}

/** A walk over the steps: forward, sometimes back one step (a revisit), ending early unless done. */
function walk(random: SeededRandom, finished: boolean): string[] {
  const path: string[] = [STEPS[0]];
  let at = 0;
  while (at < STEPS.length - 1 && path.length < 12) {
    if (at > 1 && random.chance(0.15)) {
      at -= 1;
    } else if (!finished && random.chance(0.2)) {
      break;
    } else {
      at += 1;
    }
    path.push(STEPS[at] ?? 'done');
  }
  return path;
}

export interface Population {
  readonly people: readonly Person[];
  readonly cases: readonly CaseRecord[];
}

export function population(seed: number, perDay: number): Population {
  const random = seededRandom(seed);
  const people = DAYS.flatMap((day) => Array.from({ length: perDay }, () => person(random, day)));
  const cases = DAYS.flatMap((day) =>
    Array.from({ length: Math.ceil(perDay / 3) }, (): CaseRecord => {
      const resolved = random.chance(0.7);
      const slaMet = resolved && random.chance(0.8);
      return {
        day,
        source: random.chance(0.1) ? 'redacted' : 'facts',
        resolved,
        slaMet,
        slaMissed: !slaMet && random.chance(0.5),
        resolutionSeconds: resolved ? Math.exp(random.next() * Math.log(86_400 * 20)) : null,
        assignee: random.pick([
          'usr_synthetic00000000000000001',
          'usr_synthetic00000000000000002',
          null,
        ]),
      };
    }),
  );
  return { people, cases };
}

// The rollup rows, one per key, as the rollup SQL would write them ---------------------------------

const keyOf = (day: string, source: AnalyticsRollupSource): AnalyticsRowKey => ({
  environmentId: ENVIRONMENT,
  day,
  timeZone: TIME_ZONE,
  source,
});

function grouped<Item, Row>(
  items: readonly Item[],
  key: (item: Item) => string,
  start: (item: Item) => Row,
  add: (row: Row, item: Item) => void,
): Row[] {
  const rows = new Map<string, Row>();
  for (const item of items) {
    const id = key(item);
    let row = rows.get(id);
    if (row === undefined) {
      row = start(item);
      rows.set(id, row);
    }
    add(row, item);
  }
  return [...rows.values()];
}

type Mutable<T> = { -readonly [K in keyof T]: T[K] };

const histogram = () => Array.from({ length: DURATION_BUCKET_COUNT }, () => 0);

export function inquiryRows(people: readonly Person[]): AnalyticsInquiryDailyRow[] {
  return grouped(
    people,
    (p) => [p.day, p.source, p.platform, p.deviceKind].join('|'),
    (p): Mutable<AnalyticsInquiryDailyRow> => ({
      ...keyOf(p.day, p.source),
      inquiryTemplateId: TEMPLATE,
      inquiryTemplateVersionId: VERSION,
      platform: p.platform,
      deviceKind: p.deviceKind,
      created: 0,
      started: 0,
      interacted: 0,
      finished: 0,
      completed: 0,
      completedVerified: 0,
      completedWithFallback: 0,
      completedUnverified: 0,
      failed: 0,
      expiredBeforeStart: 0,
      expiredAfterStart: 0,
      approved: 0,
      declined: 0,
      needsReview: 0,
      markedForReview: 0,
      decidedAutomatic: 0,
      decidedManual: 0,
      decidedNotDeclared: 0,
      finishSecondsHistogram: histogram(),
    }),
    (row, p) => {
      const bump = (column: keyof AnalyticsInquiryDailyRow, when: boolean) => {
        if (when) {
          (row as unknown as Record<string, number>)[column] =
            ((row as unknown as Record<string, number>)[column] ?? 0) + 1;
        }
      };
      bump('created', true);
      bump('started', p.started);
      bump('interacted', p.interacted);
      bump('finished', p.finished);
      bump('completed', p.status === 'completed');
      bump('completedVerified', p.split === 'verified');
      bump('completedWithFallback', p.split === 'with-fallback');
      bump('completedUnverified', p.split === 'unverified');
      bump('failed', p.status === 'failed');
      bump('expiredBeforeStart', p.expiredBeforeStart);
      bump('expiredAfterStart', p.expiredAfterStart);
      bump('approved', p.status === 'approved');
      bump('declined', p.status === 'declined');
      bump('needsReview', p.status === 'needs_review');
      bump('markedForReview', p.markedForReview);
      bump('decidedAutomatic', p.decided === 'automatic');
      bump('decidedManual', p.decided === 'manual');
      bump('decidedNotDeclared', p.decided === 'not-declared');
      if (p.finishSeconds !== null) {
        const histogramOf = row.finishSecondsHistogram as number[];
        const at = durationBucketOf(p.finishSeconds);
        histogramOf[at] = (histogramOf[at] ?? 0) + 1;
      }
    },
  );
}

const visibleStepRow = (day: string, source: AnalyticsRollupSource) => ({
  ...keyOf(day, source),
  inquiryTemplateId: TEMPLATE,
  inquiryTemplateVersionId: VERSION,
});

export function funnelRows(people: readonly Person[]): {
  steps: AnalyticsStepDailyRow[];
  transitions: AnalyticsTransitionDailyRow[];
  paths: AnalyticsPathDailyRow[];
} {
  const visits = people.flatMap((p) =>
    [...new Set(p.path)].map((stepId) => ({
      p,
      stepId,
      entries: p.path.filter((step) => step === stepId).length,
      exited: p.path.slice(0, -1).includes(stepId),
    })),
  );
  const steps = grouped(
    visits,
    (visit) => [visit.p.day, visit.p.source, visit.stepId].join('|'),
    (visit): Mutable<AnalyticsStepDailyRow> => ({
      ...visibleStepRow(visit.p.day, visit.p.source),
      stepId: visit.stepId,
      entered: 0,
      exited: 0,
      revisits: 0,
    }),
    (row, visit) => {
      row.entered += 1;
      row.exited += visit.exited ? 1 : 0;
      row.revisits += visit.entries > 1 ? 1 : 0;
    },
  );
  const moves = people.flatMap((p) =>
    // AL6 (K9-24): the first step is entered from the reserved start, as the rollup writes it.
    p.path.map((to, index) => ({
      p,
      from: index === 0 ? ANALYTICS_FLOW_START_STEP_ID : (p.path[index - 1] ?? ''),
      to,
    })),
  );
  const transitions = grouped(
    moves,
    (move) => [move.p.day, move.p.source, move.from, move.to].join('|'),
    (move): Mutable<AnalyticsTransitionDailyRow> => ({
      ...visibleStepRow(move.p.day, move.p.source),
      fromStepId: move.from,
      toStepId: move.to,
      count: 0,
    }),
    (row) => {
      row.count += 1;
    },
  );
  const paths = grouped(
    people.filter((p) => p.path.length > 0),
    (p) => [p.day, p.source, p.path.join('>')].join('|'),
    (p): Mutable<AnalyticsPathDailyRow> => ({
      ...visibleStepRow(p.day, p.source),
      pathSha256: pathSha256(p.path),
      stepIds: p.path,
      count: 0,
    }),
    (row) => {
      row.count += 1;
    },
  );
  return { steps, transitions, paths };
}

export const pathSha256 = (path: readonly string[]) =>
  createHash('sha256').update(JSON.stringify(path)).digest('hex');

export function verificationRows(people: readonly Person[]): {
  attempts: AnalyticsVerificationDailyRow[];
  steps: AnalyticsVerificationStepDailyRow[];
} {
  const attempts = grouped(
    people.flatMap((p) => p.attempts.map((attempt) => ({ p, attempt }))),
    ({ p, attempt }) =>
      [p.day, p.source, attempt.type, attempt.captureMethod, attempt.country].join('|'),
    ({ p, attempt }): Mutable<AnalyticsVerificationDailyRow> => ({
      ...visibleStepRow(p.day, p.source),
      verificationType: attempt.type,
      captureMethod: attempt.captureMethod,
      country: attempt.country,
      created: 0,
      submitted: 0,
      passed: 0,
      failed: 0,
      requiresRetry: 0,
      skipped: 0,
      needsReview: 0,
      canceled: 0,
    }),
    (row, { attempt }) => {
      row.created += 1;
      const submitted = ['passed', 'failed', 'requires_retry', 'needs_review'].includes(
        attempt.status,
      );
      row.submitted += submitted ? 1 : 0;
      row.passed += attempt.status === 'passed' ? 1 : 0;
      row.failed += attempt.status === 'failed' ? 1 : 0;
      row.requiresRetry += attempt.status === 'requires_retry' ? 1 : 0;
      row.skipped += attempt.status === 'skipped' ? 1 : 0;
      row.needsReview += attempt.status === 'needs_review' ? 1 : 0;
      row.canceled += attempt.status === 'canceled' ? 1 : 0;
    },
  );
  const steps = grouped(
    people.filter((p) => p.attempts.length > 0),
    (p) => [p.day, p.source].join('|'),
    (p): Mutable<AnalyticsVerificationStepDailyRow> => ({
      ...visibleStepRow(p.day, p.source),
      stepId: 'document',
      verificationType: 'government-id',
      entered: 0,
      passed: 0,
      failedAfterAttempts: 0,
      needsReview: 0,
      skipped: 0,
    }),
    (row, p) => {
      const last = p.attempts[p.attempts.length - 1]?.status;
      row.entered += 1;
      row.passed += last === 'passed' ? 1 : 0;
      row.failedAfterAttempts += last === 'failed' || last === 'requires_retry' ? 1 : 0;
      row.needsReview += last === 'needs_review' ? 1 : 0;
      row.skipped += last === 'skipped' ? 1 : 0;
    },
  );
  return { attempts, steps };
}

export function checkRows(people: readonly Person[]): {
  results: AnalyticsCheckDailyRow[];
  reasons: AnalyticsCheckReasonDailyRow[];
} {
  const results = people.flatMap((p) => p.checks.map((check) => ({ p, check })));
  return {
    results: grouped(
      results,
      ({ p, check }) => [p.day, p.source, check.name, check.status].join('|'),
      ({ p, check }): Mutable<AnalyticsCheckDailyRow> => ({
        ...visibleStepRow(p.day, p.source),
        verificationType: 'government-id',
        checkName: check.name,
        requirement: 'required',
        status: check.status,
        count: 0,
      }),
      (row) => {
        row.count += 1;
      },
    ),
    reasons: grouped(
      results.flatMap(({ p, check }) => check.reasons.map((reason) => ({ p, check, reason }))),
      ({ p, check, reason }) => [p.day, p.source, check.name, reason].join('|'),
      ({ p, check, reason }): Mutable<AnalyticsCheckReasonDailyRow> => ({
        ...visibleStepRow(p.day, p.source),
        verificationType: 'government-id',
        checkName: check.name,
        requirement: 'required',
        reason,
        count: 0,
      }),
      (row) => {
        row.count += 1;
      },
    ),
  };
}

export function caseRows(cases: readonly CaseRecord[]): {
  cases: AnalyticsCaseDailyRow[];
  assignees: AnalyticsCaseAssigneeDailyRow[];
} {
  return {
    cases: grouped(
      cases,
      (c) => [c.day, c.source].join('|'),
      (c): Mutable<AnalyticsCaseDailyRow> => ({
        ...keyOf(c.day, c.source),
        caseTemplateId: CASE_TEMPLATE,
        created: 0,
        resolved: 0,
        slaMet: 0,
        slaMissed: 0,
        resolutionSecondsHistogram: histogram(),
      }),
      (row, c) => {
        row.created += 1;
        row.resolved += c.resolved ? 1 : 0;
        row.slaMet += c.slaMet ? 1 : 0;
        row.slaMissed += c.slaMissed ? 1 : 0;
        if (c.resolutionSeconds !== null) {
          const histogramOf = row.resolutionSecondsHistogram as number[];
          const at = durationBucketOf(c.resolutionSeconds);
          histogramOf[at] = (histogramOf[at] ?? 0) + 1;
        }
      },
    ),
    assignees: grouped(
      cases.filter((c) => c.assignee !== null),
      (c) => [c.day, c.source, c.assignee].join('|'),
      (c): Mutable<AnalyticsCaseAssigneeDailyRow> => ({
        ...keyOf(c.day, c.source),
        caseTemplateId: CASE_TEMPLATE,
        userId: c.assignee,
        assigned: 0,
        resolved: 0,
      }),
      (row, c) => {
        row.assigned += 1;
        row.resolved += c.resolved ? 1 : 0;
      },
    ),
  };
}

export function signalRows(people: readonly Person[], name: string): AnalyticsSignalDailyRow[] {
  return grouped(
    people,
    (p) =>
      [p.day, p.source, p.platform, p.deviceKind, signalBinOf(name, p.signals[name])].join('|'),
    (p): Mutable<AnalyticsSignalDailyRow> => ({
      ...keyOf(p.day, p.source),
      inquiryTemplateId: TEMPLATE,
      inquiryTemplateVersionId: VERSION,
      platform: p.platform,
      deviceKind: p.deviceKind,
      signalName: name,
      bin: signalBinOf(name, p.signals[name]),
      count: 0,
    }),
    (row) => {
      row.count += 1;
    },
  );
}
